float lcg(uint seed) {
    const uint a = 1235345171u;
    const uint c = 1456332734u;
    const uint m = 1294967292u;
    seed = (a * seed + c) % m;
    return float(seed) / float(m); // [0, 1)
}


void mainImage(out vec4 fragColor, in vec2 fragCoord) {

//play with me
uint playwithme = 1123u*uint(iTime*1.);

    vec2 uv = fragCoord / iResolution.xy;
    uv*=0.005;
    uint seed = uint(uv.x * 14403.0) + uint(uv.y * 1440.24) * playwithme;

    vec3 col = vec3(lcg(seed));

    //color version
    // col = vec3(lcg(seed),lcg(seed+3u), lcg(seed+10u));

    fragColor = vec4(col, 1.0);
}
